from pathlib import Path
import json, html
root=Path(__file__).resolve().parents[1]
listing=json.loads((root/'listing.json').read_text())
esc=html.escape
groups=[('apple/iphone','iPhone','1206 × 2622'),('apple/iphone-duo-outer','Duo cerrado','1398 × 2034'),('apple/iphone-duo-inner','Duo abierto','2853 × 2007'),('apple/ipad-13','iPad 13″','2048 × 2732'),('google-play/phone','Android móvil','1080 × 1920'),('google-play/tablet-7','Tablet 7″','1080 × 1920'),('google-play/tablet-10','Tablet 10″','1440 × 2560')]
head='''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sanuk · Kit de publicación 1.0</title><style>
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;color:#1D2347;background:#F3F6FA;font-family:ui-sans-serif,system-ui,-apple-system,sans-serif;line-height:1.6}button,a,select{touch-action:manipulation}a{color:#2257D6;text-underline-offset:4px}header{padding:20px max(24px,calc((100vw - 1240px)/2));display:flex;justify-content:space-between;align-items:center;gap:24px;border-bottom:1px solid #DFE5EF;background:#fff}header strong{font-size:22px}header span{font-size:12px;color:#5F6988}nav{display:flex;gap:22px;flex-wrap:wrap}nav a{text-decoration:none;font-size:14px;font-weight:700;color:inherit}main{max-width:1290px;margin:auto;padding:38px 24px 80px}.hero{border-radius:28px;overflow:hidden;background:#FFE2B8;position:relative}.hero img{width:100%;display:block}.hero-label{position:absolute;top:26px;left:30px;font-size:12px;letter-spacing:.13em;font-weight:800;text-transform:uppercase}.intro{display:flex;justify-content:space-between;align-items:flex-end;gap:24px;padding:30px 0 34px}.intro h1{font-size:clamp(27px,4vw,43px);letter-spacing:-.04em;line-height:1.1;margin:0 0 12px}.intro p{margin:0;color:#5F6988;max-width:650px}.pill{padding:8px 14px;border-radius:30px;background:#E1F4E9;color:#126A40;font-size:12px;font-weight:800;white-space:nowrap}section{margin-top:54px;scroll-margin-top:24px}h2{font-size:27px;letter-spacing:-.03em;margin:0 0 6px}h3{font-size:17px;margin:0}p.sub{color:#5F6988;margin:0 0 22px}button,select{font:inherit}button{cursor:pointer}.selector{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:22px}.selector button{border:1px solid #D4DCE9;background:white;color:#1D2347;padding:10px 16px;border-radius:30px;font-size:13px;font-weight:750}.selector button[aria-selected=true]{background:#1D2347;color:white;border-color:#1D2347}.screens{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:18px}.screens a{display:block;text-decoration:none;color:inherit;min-width:0}.screens img{display:block;width:100%;height:auto;border-radius:9px;box-shadow:0 6px 20px #1d23470a}.screens small{display:block;font-size:11px;margin-top:10px;color:#5F6988}.group[hidden]{display:none}.group-heading{display:flex;justify-content:space-between;margin-bottom:17px;font-size:13px;color:#5F6988}.artgrid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.card{background:#fff;border:1px solid #DFE5EF;border-radius:19px;padding:22px;min-width:0}.card img{display:block;width:100%;border-radius:12px;margin-bottom:17px}.card p{font-size:13px;color:#5F6988;margin:8px 0}.card a{font-size:13px}.wide{grid-column:1/-1}.logos{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.logo-tile{border-radius:15px;background:#fff;padding:16px;border:1px solid #DFE5EF}.logo-tile img{width:100%;height:140px;object-fit:contain}.logo-tile.dark{background:#1D2347;color:white}.logo-tile a{font-size:12px;margin-right:10px}.logo-tile.dark a{color:white}.icon-row{display:flex;gap:24px;margin-bottom:20px;align-items:center}.icon-row img{width:100px;height:100px;border-radius:22px}.icon-row div{flex:1}.metadata{display:grid;grid-template-columns:1fr 1fr;gap:20px}.field{padding:17px 0;border-top:1px solid #E8EDF4}.field:first-of-type{border-top:0}.label{display:flex;align-items:center;justify-content:space-between;gap:15px;font-size:12px;font-weight:800;color:#5F6988;margin-bottom:7px}.copy{border:0;background:#EDF2F8;color:#1D2347;padding:6px 10px;border-radius:7px;font-size:11px;font-weight:800}.value{white-space:pre-wrap;font-size:14px;overflow-wrap:anywhere}.long{max-height:340px;overflow:auto;padding-right:10px}.todo{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.todo .number{width:30px;height:30px;background:#FFF0D6;color:#936112;display:grid;place-items:center;border-radius:9px;font-weight:900;font-size:13px;margin-bottom:14px}.todo p{font-size:14px;color:#5F6988}.downloads{display:flex;gap:18px;flex-wrap:wrap;margin-top:24px;font-size:14px}footer{margin-top:50px;border-top:1px solid #D4DCE9;padding-top:24px;color:#5F6988;font-size:12px}dialog{width:min(94vw,1200px);max-height:94vh;padding:12px;border:0;border-radius:14px;background:#F3F6FA}dialog::backdrop{background:#10152Cdd}dialog img{display:block;max-width:100%;max-height:84vh;margin:auto;object-fit:contain}dialog button{position:absolute;right:16px;top:16px;border:0;border-radius:30px;width:35px;height:35px;font-size:21px;background:#fff;color:#1D2347}dialog a{display:block;text-align:center;font-size:12px;margin-top:7px}:focus-visible{outline:3px solid #FFA41B;outline-offset:4px}
@media(max-width:800px){nav{gap:12px}.intro{display:block}.pill{display:inline-block;margin-top:20px}.screens{grid-template-columns:repeat(2,minmax(0,1fr))}.artgrid,.metadata{grid-template-columns:1fr}.logos,.todo{grid-template-columns:1fr}.logo-tile img{height:110px}header{padding:18px 24px;align-items:flex-start}nav a{font-size:12px}.hero-label{top:13px;left:17px;font-size:8px}main{padding-top:24px}.wide{grid-column:auto}}
</style></head><body><header><div><strong>Sanuk</strong><br><span>PUBLICACIÓN · 1.0</span></div><nav><a href="#capturas">Capturas</a><a href="#creativos">Creativos</a><a href="#marca">Marca</a><a href="#textos">Textos</a><a href="#envio">Envío</a></nav></header><main><div class="hero"><img src="apple/creative/header.png" alt="Noi entre las montañas y la carretera de Sanuk"><span class="hero-label">Thai, curva a curva</span></div><div class="intro"><div><h1>El primer viaje de Sanuk.</h1><p>Recursos para App Store y Google Play. Textos de App Store en español e inglés, capturas de la app e identidad visual lista para exportar.</p></div><span class="pill">100 % gratuita · Mikel Garcia</span></div>'''
parts=[head,'<section id="capturas"><h2>Una historia. Cada pantalla.</h2><p class="sub">Selecciona el dispositivo. Toca una imagen para ampliarla o descargar el original.</p><div class="selector" role="tablist" aria-label="Dispositivo">']
for i,(folder,name,size) in enumerate(groups):
    parts.append(f'<button role="tab" aria-selected="{str(i==0).lower()}" data-group="g{i}" id="t{i}" aria-controls="g{i}">{esc(name)}</button>')
parts.append('</div>')
for i,(folder,name,size) in enumerate(groups):
    files=sorted((root/folder).glob('*.png'))
    parts.append(f'<div class="group" id="g{i}" role="tabpanel" aria-labelledby="t{i}" {"hidden" if i else ""}><div class="group-heading"><strong>{esc(name)}</strong><span>{len(files)} capturas · {size} px</span></div><div class="screens">')
    for f in files:
        rel=str(f.relative_to(root));label=f.stem.split('-',1)[1].replace('-',' ').title()
        parts.append(f'<a class="preview" href="{rel}"><img loading="lazy" src="{rel}" alt="Captura de Sanuk, {esc(label)}, {esc(name)}"><small>{esc(f.name)}</small></a>')
    parts.append('</div></div>')
parts.append('''</section><section id="creativos"><h2>El norte de Tailandia, en portada.</h2><p class="sub">Arte de marca para los espacios editoriales de Apple y el gráfico de funciones de Google Play.</p><div class="artgrid">''')
for src,name,size,source,guide in [('apple/creative/header.png','App Store · Header','3840 × 1646','sources/header.svg','checks/header-safe-area.png'),('apple/creative/search-results.png','App Store · Search Results','3840 × 2560','sources/search.svg','checks/search-safe-area.png'),('google-play/feature-graphic.png','Google Play · Feature graphic','1024 × 500','sources/feature.svg',None)]:
    parts.append(f'<article class="card"><a class="preview" href="{src}"><img src="{src}" alt="{name}"></a><h3>{name}</h3><p>{size} px · PNG sin transparencia</p><a href="{src}" download>Descargar PNG</a> · <a href="{source}" download>SVG editable</a>{f" · <a class=preview href={guide}>Área segura</a>" if guide else ""}</article>')
parts.append('''<article class="card"><h3>Conservar la composición</h3><p>Los elementos principales de Apple quedan dentro de sus áreas seguras. Las imágenes con guías rosas sirven para revisar y se guardan en checks. Los originales para subir están en apple/creative.</p><p>El header y Search Results se gestionan como recursos creativos, por separado de las capturas de pantalla.</p><p>Todos los tamaños y destinos están documentados en la guía de publicación.</p><a href="README.md">Abrir la guía</a></article></div></section><section id="marca"><h2>Noi lleva el equipaje.</h2><p class="sub">Iconos y logotipos basados en la identidad original de Sanuk.</p><div class="card icon-row"><img src="brand/app-icon-ios-1024.png" alt="Icono de Sanuk con Noi"><div><h3>Iconos de tienda</h3><p>Apple 1024 × 1024 RGB · Google Play 512 × 512 RGBA</p><a href="brand/app-icon-ios-1024.png" download>Icono Apple</a> · <a href="brand/app-icon-google-512.png" download>Icono Google Play</a> · <a href="brand/brand-notes.txt">Colores y fuentes</a></div></div><div class="logos">''')
for name,dark in [('navy',False),('white',True),('warm',False)]:
    parts.append(f'<div class="logo-tile {"dark" if dark else ""}"><img src="brand/logo-{name}.png" alt="Logotipo de Sanuk, variante {name}"><a href="brand/logo-{name}.png" download>PNG</a><a href="brand/logo-{name}.svg" download>SVG editable</a></div>')
parts.append('</div></section><section id="textos"><h2>Palabras listas para las tiendas.</h2><p class="sub">La ficha presenta el aprendizaje desde cero, los 20 juegos y el viaje con Noi. Cada campo respeta el límite de su tienda.</p><div class="metadata">')
apple_fields=[('Nombre','name',30),('Subtítulo','subtitle',30),('Texto promocional','promotional-text',170),('Palabras clave','keywords',100),('Descripción','description',4000),('Novedades','release-notes',4000)]
cards=[('App Store',locale,[(label,f'apple/{locale}/{filename}.txt',limit) for label,filename,limit in apple_fields]) for locale in listing['appleLocalizations']]
cards.append(('Google Play','es-ES',[('Título','google-play/es-ES/title.txt',30),('Descripción breve','google-play/es-ES/short-description.txt',80),('Descripción completa','google-play/es-ES/full-description.txt',4000),('Novedades','google-play/es-ES/release-notes.txt',500)]))
for platform,locale,fields in cards:
    parts.append(f'<article class="card {"wide" if platform=="Google Play" else ""}"><h3>{platform} · {locale}</h3>')
    for label,file,limit in fields:
        text=(root/file).read_text().strip();uid=file.replace('/','-').replace('.','-')
        length=len(text.encode()) if label=='Palabras clave' else len(text)
        parts.append(f'<div class="field"><div class="label"><span>{label} · {length}/{limit}</span><button class="copy" data-copy="{uid}">Copiar</button></div><div id="{uid}" lang="{locale}" class="value {"long" if len(text)>800 else ""}">{esc(text)}</div></div>')
    parts.append('</article>')
parts.append('''</div></section><section id="envio"><h2>Últimos pasos para publicar.</h2><p class="sub">El paquete queda preparado localmente. Estos pasos dependen del sitio y de las cuentas del titular.</p><div class="todo"><article class="card"><span class="number">01</span><h3>Publicar el sitio</h3><p>Activar sanuk.overlayon.com con las páginas /privacidad y /soporte. Verificar también el correo sanuk@overlayon.com.</p><a href="legal/privacidad.html">Ver privacidad preparada</a><br><a href="legal/soporte.html">Ver soporte preparado</a></article><article class="card"><span class="number">02</span><h3>Preparar los binarios</h3><p>Generar el IPA y el AAB firmados desde el perfil production de EAS, probarlos en TestFlight y Play y comprobar el target API del AAB.</p><a href="README.md">Comandos y comprobaciones</a></article><article class="card"><span class="number">03</span><h3>Completar las consolas</h3><p>Introducir identidad, contacto privado, territorios y respuestas de contenido y privacidad. Revisar si aplica la prueba cerrada de la cuenta personal de Google.</p><a href="review/privacy-and-content.md">Declaraciones propuestas</a><br><a href="review/review-notes-en.txt">Notas para App Review</a></article></div><div class="downloads"><a href="README.md">Guía completa</a><a href="listing.json">Ficha estructurada</a><a href="google-play/alt-texts.tsv">Textos alternativos</a><a href="checks/validation.json">Validación del paquete</a><a href="sources/capture-manifest.json">Procedencia de las capturas</a></div></section><footer>Sanuk 1.0 · Preparado el 16 de noviembre de 2026 · Mikel Garcia · sanuk@overlayon.com<br>Capturas nativas con progreso local de demostración. Los binarios de producción y la publicación del sitio se completan desde las cuentas del titular.</footer></main><dialog id="viewer"><button aria-label="Cerrar imagen">×</button><img alt="Vista ampliada"><a download>Descargar original</a></dialog><script>
document.querySelectorAll('[data-group]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-group]').forEach(x=>x.setAttribute('aria-selected',String(x===b)));document.querySelectorAll('.group').forEach(g=>g.hidden=g.id!==b.dataset.group);}));
document.querySelectorAll('[data-copy]').forEach(b=>b.addEventListener('click',async()=>{const t=document.getElementById(b.dataset.copy).innerText;try{await navigator.clipboard.writeText(t);}catch{const a=document.createElement('textarea');a.value=t;document.body.append(a);a.select();document.execCommand('copy');a.remove();}b.textContent='Copiado';setTimeout(()=>b.textContent='Copiar',1600);}));
const viewer=document.getElementById('viewer');document.querySelectorAll('a.preview').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();viewer.querySelector('img').src=a.href;viewer.querySelector('img').alt=a.querySelector('img')?.alt||'Recurso de Sanuk';viewer.querySelector('a').href=a.href;viewer.showModal();}));viewer.querySelector('button').onclick=()=>viewer.close();viewer.addEventListener('click',e=>{if(e.target===viewer)viewer.close();});
</script></body></html>''')
(root/'index.html').write_text(''.join(parts))
print('Catálogo generado')
